const $=s=>document.querySelector(s), app=$('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allCards=langs.flatMap(l=>l.cards.map(c=>({...c,lang:l.id}))),cardIds=new Set(allCards.map(c=>c.id)),languageIds=new Set(langs.map(l=>l.id));
const DEFAULT={selected:[...LIGHT_IDS],known:[],ui:'pt',reviews:{},daily:{},kind:'all',slow:false};
let state,volatile=false;
function migrateState(s){if(!s||typeof s!=='object')return s;return {...s,known:s.known===undefined?[]:s.known,ui:s.ui===undefined?'pt':s.ui};}
function validState(s){return s&&['pt','en'].includes(s.ui)&&Array.isArray(s.known)&&s.known.every(id=>languageIds.has(id))&&Array.isArray(s.selected)&&s.selected.every(id=>languageIds.has(id))&&s.reviews&&typeof s.reviews==='object'&&!Array.isArray(s.reviews)&&Object.entries(s.reviews).every(([id,r])=>cardIds.has(id)&&r&&['due','interval','reps','last'].every(k=>typeof r[k]==='number'&&Number.isFinite(r[k])&&r[k]>=0))&&s.daily&&typeof s.daily==='object'&&!Array.isArray(s.daily)&&Object.entries(s.daily).every(([d,n])=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isInteger(n)&&n>=0)&&['all','phrase','word'].includes(s.kind)&&typeof s.slow==='boolean';}
function cleanState(s){return {...s,known:[...new Set(s.known)],selected:[...new Set(s.selected)].filter(id=>!s.known.includes(id))};}
try{state=migrateState(JSON.parse(localStorage.getItem('passaporte-v1'))||structuredClone(DEFAULT));}catch{state=structuredClone(DEFAULT);volatile=true;}
if(!validState(state)){state=structuredClone(DEFAULT);volatile=true;}state=cleanState(state);
const t=(pt,en)=>state.ui==='en'?en:pt;
const lname=l=>state.ui==='en'?englishLanguages[l.id][0]:l.name;
const lwhere=l=>state.ui==='en'?englishLanguages[l.id][1]:l.where;
const lculture=l=>state.ui==='en'?englishLanguages[l.id][2]:l.culture;
const meaning=c=>state.ui==='en'?englishMeanings[c.pt]:c.pt;
const rname=r=>state.ui==='en'?englishRegions[r[0]][0]:r[1];
const rdesc=r=>state.ui==='en'?englishRegions[r[0]][1]:r[3];
const available=()=>langs.filter(l=>!state.known.includes(l.id));
const selection=()=>state.selected.filter(id=>!state.known.includes(id));
function scriptHTML(c,l){l=l||langs.find(l=>l.id===(c.lang||c.id.split('-')[0]));return `<span class="script-stack"><bdi class="native" lang="${l.locale}" dir="auto">${esc(c.native)}</bdi>${c.nativeAlt?`<bdi class="native" lang="ur" dir="rtl">${esc(c.nativeAlt)}</bdi>`:''}${c.native!==c.roman||c.nativeAlt?`<span class="roman" lang="${l.id}-Latn" dir="ltr">${esc(c.roman)}</span>`:''}</span>`;}
function save(){try{localStorage.setItem('passaporte-v1',JSON.stringify(state));}catch{volatile=true;toast(t('Não foi possível salvar. Exporte seu progresso nas configurações.','Could not save. Export your progress in Settings.'));}}
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
let region='all',page='explorar',search='',session=null,voices=[],catalogCollection='regions';
function loadVoices(){voices=window.speechSynthesis?.getVoices()||[];}loadVoices();if(window.speechSynthesis)speechSynthesis.addEventListener('voiceschanged',loadVoices);
function voiceFor(l){return voices.find(v=>v.lang.toLowerCase()===l.locale.toLowerCase())||voices.find(v=>v.lang.split('-')[0]===l.locale.split('-')[0]);}
function speak(id){const c=allCards.find(c=>c.id===id),l=langs.find(l=>l.id===c.lang);loadVoices();const voice=voiceFor(l);if(!voice){toast(t('Nenhuma voz de '+lname(l)+' disponível neste aparelho.','No '+lname(l)+' voice is available on this device.'));return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(c.native);u.voice=voice;u.lang=voice.lang;u.rate=state.slow?.7:.9;u.onerror=()=>toast(t('Áudio indisponível. Tente novamente ou verifique as vozes do aparelho.','Audio unavailable. Try again or check your device’s voices.'));speechSynthesis.speak(u);}
function audioButton(c){return `<button class="audio" data-speak="${c.id}" aria-label="${esc(t('Ouvir','Listen')+' '+c.roman)}">◖)) ${t('Ouvir','Listen')}</button>`;}
function bindAudio(){document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));}
function dueCount(){return allCards.filter(c=>selection().includes(c.lang)&&state.reviews[c.id]?.due<=Date.now()).length;}
function selectedCount(){return selection().length;}
function syncChrome(){document.documentElement.lang=state.ui==='en'?'en':'pt-BR';document.title=t('Passaporte — um mundo de conversas','Passaporte — a world of conversations');$('.beta').textContent=t('ATELIÊ DE IDIOMAS','LANGUAGE ATELIER');$('#settings').setAttribute('aria-label',t('Abrir configurações','Open settings'));$('.brand').setAttribute('aria-label',t('Passaporte, início','Passaporte, home'));$('.bottom').setAttribute('aria-label',t('Navegação principal','Main navigation'));$('.modal-close').setAttribute('aria-label',t('Fechar janela','Close dialog'));$('#ui-language').value=state.ui;$('#ui-language').setAttribute('aria-label',t('Idioma do site','Site language'));document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.querySelector('span').textContent=({explorar:t('Explorar','Explore'),revisar:t('Revisar','Review'),passaporte:t('Meu passaporte','My passport')})[b.dataset.page];});}
function changeUI(ui){if(!['pt','en'].includes(ui))return;state.ui=ui;save();if(window.speechSynthesis)speechSynthesis.cancel();render();}
function navigate(p){if(session){openModal(`<h2>${t('Pausar esta sessão?','Pause this session?')}</h2><p>${t('Os cartões já respondidos estão salvos. Os demais continuam disponíveis.','Answered cards are saved. The remaining cards will still be available.')}</p><button class="btn" id="confirm-exit">${t('Pausar e sair','Pause and leave')}</button>`);$('#confirm-exit').onclick=()=>{session=null;$('#modal').close();navigate(p);};return;}page=p;render();window.scrollTo(0,0);}
function render(){syncChrome();if(session)return renderSession();if(page==='explorar')renderExplore();else if(page==='revisar')renderReview();else renderPassport();}
const illustration=`<div class="art" aria-hidden="true"><svg viewBox="0 0 370 280" fill="none"><path d="M33 222C96 161 275 290 338 159" stroke="#bc9870" stroke-dasharray="4 7"/><circle cx="187" cy="128" r="107" fill="#e8ecdd"/><circle cx="187" cy="128" r="87" stroke="#68816a" stroke-width="1.5"/><ellipse cx="187" cy="128" rx="42" ry="87" stroke="#84987a"/><ellipse cx="187" cy="128" rx="72" ry="87" stroke="#a3b199"/><ellipse cx="187" cy="128" rx="87" ry="34" stroke="#84987a"/><path d="M100 128H274M187 41V215M115 81H260M115 176H260" stroke="#84987a"/><path d="M208 27L261 45L247 53L240 70Z" fill="#c97955"/><path d="M240 70L240 47L208 27" stroke="#f8e4cc"/><circle cx="127" cy="154" r="7" fill="#c97955" stroke="#f8f6ef" stroke-width="3"/><circle cx="230" cy="112" r="7" fill="#c97955" stroke="#f8f6ef" stroke-width="3"/><path d="M127 154Q167 100 230 112" stroke="#c97955" stroke-width="2" stroke-dasharray="3 5"/><rect x="229" y="196" width="73" height="58" rx="5" fill="#f3e6d1" stroke="#be9770" transform="rotate(12 229 196)"/><text x="262" y="222" text-anchor="middle" fill="#a37850" font-size="9" transform="rotate(12 262 222)">BON VOYAGE</text><path d="M249 232L275 236" stroke="#be9770"/></svg><span class="bubble b1">Kia ora!</span><span class="bubble b2">Selamat pagi</span><span class="bubble b3">Um mundo de olás.</span></div>`;
function renderExplore(){syncChrome();const art=illustration.replace('Um mundo de olás.',t('Um mundo de olás.','A world of hellos.'));app.innerHTML=`<section class="hero"><div><div class="eyebrow">${t('PEQUENAS FRASES. GRANDES ENCONTROS.','SMALL PHRASES. GREAT ENCOUNTERS.')}</div><h1>${t('O mundo começa<br>com um <em>olá.</em>','The world begins<br>with a <em>hello.</em>')}</h1><p class="sub">${t('Um pouco de cada língua. Um novo jeito de conhecer pessoas, lugares e culturas.','A little of every language. A new way to meet people, places and cultures.')}</p><div class="hero-buttons"><button class="btn" id="learn-all">${t('Começar pelo Light','Start with Light')} ↗</button><button class="btn secondary" id="my-route">${t('Minha rota','My route')} · ${selectedCount()}</button></div></div>${art}</section><div class="trip-strip"><div><span class="strip-icon">✧</span><div><b>${state.daily[dateKey()]||0} ${t('encontros com palavras hoje','word encounters today')}</b><p>${dueCount()} ${t('cartões para rever · no seu ritmo','cards to review · at your own pace')}</p></div></div><button class="text-btn" id="go-review">${t('Ver revisões','See reviews')} →</button></div>${collectionsHTML()}<section id="catalog-section"><div class="section-row"><div><h2>${t('Para onde vamos?','Where shall we go?')}</h2><p>${t('Escolha uma região ou siga sua curiosidade.','Choose a region or follow your curiosity.')}</p></div><input class="search" type="search" placeholder="${t('Buscar idioma ou lugar…','Search a language or place…')}" aria-label="${t('Buscar idioma ou lugar','Search a language or place')}" value="${esc(search)}" id="search"></div><div class="filters"><button class="chip ${region==='all'?'active':''}" data-region="all">${t('Todas as regiões','All regions')}</button>${regions.map(r=>`<button class="chip ${region===r[0]?'active':''}" data-region="${r[0]}">${rname(r)}</button>`).join('')}</div><div id="catalog"></div></section><p class="notice">${t(`Edição inicial · ${langs.length} idiomas · ${allCards.length} cartões disponíveis. A meta é 100 frases e 300 palavras por idioma. Ainda não é um curso A1 completo.`,`First edition · ${langs.length} languages · ${allCards.length} cards available. The goal is 100 phrases and 300 words per language. This is not yet a complete A1 course.`)} <button class="text-btn" id="about-content">${t('Sobre o conteúdo','About the content')}</button></p>`;
$('#learn-all').onclick=()=>openCollection('light');bindCollections();$('#my-route').onclick=()=>startSession(false);$('#go-review').onclick=()=>navigate('revisar');$('#about-content').onclick=about;$('#search').oninput=e=>{search=e.target.value;renderCatalog();};document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{region=b.dataset.region;catalogCollection='regions';renderExplore();});renderCatalog();}
function renderCatalog(){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const preset=collections.find(c=>c.id===catalogCollection);const items=available().filter(l=>(catalogCollection==='regions'||preset.ids.includes(l.id))&&(region==='all'||l.region===region)&&normalize(lname(l)+' '+lwhere(l)+' '+l.name+' '+l.where).includes(normalize(search)));if($('#my-route'))$('#my-route').textContent=t('Minha rota','My route')+' · '+selectedCount();
if(catalogCollection==='regions'&&region==='all'&&!search){$('#catalog').innerHTML=`<div class="region-grid">${regions.map(r=>`<button class="region-card" data-open-region="${r[0]}" style="--tint:${r[4]}"><span class="region-icon">${r[2]}</span><span class="arrow">↗</span><h3>${rname(r)}</h3><p>${rdesc(r)}</p><footer><span>${available().filter(l=>l.region===r[0]).length} ${t('idiomas para descobrir','languages to discover')}</span></footer></button>`).join('')}</div>${state.known.length?`<p class="smallprint" style="margin-top:16px">${state.known.length} ${t('idiomas marcados como “Já sei”. Você pode restaurá-los nas configurações.','languages marked “Already know”. You can restore them in Settings.')}</p>`:''}`;document.querySelectorAll('[data-open-region]').forEach(b=>b.onclick=()=>{region=b.dataset.openRegion;renderExplore();$('#catalog').scrollIntoView({behavior:'smooth',block:'center'});});return;}
$('#catalog').innerHTML=`${selectionIntro(preset,items)}<div class="selection-bar"><span>${items.length} ${t('idiomas','languages')} · ${selectedCount()} ${t('na sua rota','on your route')}</span><button class="btn secondary small" id="select-region" ${!items.length?'disabled':''}>${t('Usar esta seleção','Use this selection')}</button><button class="btn small" id="study-region" ${!items.length?'disabled':''}>${t('Estudar estes','Study these')} →</button></div><div class="lang-grid">${items.map(l=>`<article class="lang-card"><div class="lang-top"><div><div class="lang-code">${l.id.toUpperCase()} · ${regions.find(r=>r[0]===l.region)[2]}</div><h3>${lname(l)}</h3></div><label><input type="checkbox" class="check" data-select="${l.id}" ${selection().includes(l.id)?'checked':''} aria-label="${esc(t('Incluir '+lname(l)+' na minha rota','Include '+lname(l)+' on my route'))}"></label></div><p>${lwhere(l)}</p><div class="counts">${l.cards.filter(c=>c.type==='phrase').length} ${t('frases','phrases')} · ${l.cards.filter(c=>c.type==='word').length} ${t('palavras','words')}</div><div class="lang-actions"><button class="btn secondary small" data-info="${l.id}">${t('Conhecer','Discover')}</button><button class="btn small" data-study="${l.id}">${t('Aprender','Learn')} →</button></div><button class="text-btn known-action" data-known="${l.id}">✓ ${t('Já sei este idioma','I already know this language')}</button></article>`).join('')}</div>${!items.length?`<div class="empty">${t('Nenhum idioma disponível aqui. Tente outra busca ou restaure idiomas nas configurações.','No languages available here. Try another search or restore languages in Settings.')}</div>`:''}`;
document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{state.selected=b.checked?[...new Set([...selection(),b.dataset.select])]:selection().filter(id=>id!==b.dataset.select);save();renderCatalog();});document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>languageInfo(b.dataset.info));document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>startSession(false,[b.dataset.study]));bindKnown();$('#select-region').onclick=()=>{state.selected=items.map(l=>l.id);save();renderExplore();toast(t('Sua rota agora usa esta seleção. Seu progresso foi mantido.','Your route now uses this selection. Your progress is preserved.'));};$('#study-region').onclick=()=>{state.selected=items.map(l=>l.id);save();startSession(false);};}
function markKnown(id){if(!languageIds.has(id))return;state.known=[...new Set([...state.known,id])];state.selected=state.selected.filter(x=>x!==id);save();if($('#modal').open)$('#modal').close();render();toast(t('Idioma ocultado. Você pode restaurá-lo nas configurações.','Language hidden. You can restore it in Settings.'));}
function restoreKnown(id){state.known=state.known.filter(x=>x!==id);state.selected=[...new Set([...state.selected,id])];save();render();}
function bindKnown(){document.querySelectorAll('[data-known]').forEach(b=>b.onclick=()=>markKnown(b.dataset.known));}
function openModal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function languageInfo(id){const l=langs.find(l=>l.id===id);openModal(`<span class="eyebrow">${t('UMA JANELA PARA O MUNDO','A WINDOW TO THE WORLD')}</span><h2>${lname(l)}</h2><p><b>${t('Onde ouvir:','Where to hear it:')}</b> ${lwhere(l)}.</p><p>${lculture(l)}</p><p class="smallprint">${t('Amostra inicial:','Starter sample:')} ${l.cards.filter(c=>c.type==='phrase').length}/100 ${t('frases e','phrases and')} ${l.cards.filter(c=>c.type==='word').length}/300 ${t('palavras.','words.')} ${voiceFor(l)?t('Voz sintética disponível neste aparelho.','Synthetic voice available on this device.'):t('Nenhuma voz deste idioma detectada neste aparelho.','No voice for this language detected on this device.')}</p><button class="btn full" id="modal-study">${t('Começar neste idioma','Start this language')} →</button><button class="text-btn known-action" data-known="${id}">✓ ${t('Já sei este idioma','I already know this language')}</button><div class="word-list">${l.cards.map(c=>`<div class="word-row"><div>${scriptHTML(c,l)}<p>${esc(meaning(c))}</p></div>${audioButton(c)}</div>`).join('')}</div>`);$('#modal-study').onclick=()=>{$('#modal').close();startSession(false,[id]);};bindAudio();bindKnown();}
function renderReview(){const due=dueCount();app.innerHTML=`<div class="eyebrow">${t('DÊ TEMPO À SUA MEMÓRIA','GIVE YOUR MEMORY TIME')}</div><h1>${t('Um reencontro<br>com as <em>palavras.</em>','Meet those<br><em>words</em> again.')}</h1><p class="sub">${t('Primeiro, o que está na hora de rever. Depois, novas descobertas na sua rota.','First, what’s ready for review. Then, new discoveries along your route.')}</p><div class="stat-grid"><div class="stat"><strong>${due}</strong><span>${t('revisões para agora','reviews due now')}</span></div><div class="stat"><strong>${selectedCount()}</strong><span>${t('idiomas na sua rota','languages on your route')}</span></div><div class="stat"><strong>${Object.keys(state.reviews).length}</strong><span>${t('cartões já explorados','cards explored')}</span></div></div><div class="mode-row">${[['all',t('Frases + palavras','Phrases + words')],['phrase',t('Só frases','Phrases only')],['word',t('Só palavras','Words only')]].map(([id,name])=>`<button class="chip ${state.kind===id?'active':''}" data-kind="${id}">${name}</button>`).join('')}</div><div class="hero-buttons"><button class="btn" id="review-due">${t('Rever cartões pendentes','Review due cards')} →</button><button class="btn secondary" id="review-new">${t('Aprender + revisar','Learn + review')}</button></div><p class="notice">${t('Sessões de até 10 cartões. “De novo” retorna em 10 minutos; as outras opções ampliam o intervalo conforme a dificuldade. Idiomas marcados como “Já sei” não entram nas sessões. Seu progresso fica neste navegador.','Sessions of up to 10 cards. “Again” schedules a review in 10 minutes; other choices increase the interval according to difficulty. Languages marked “Already know” stay out of sessions. Your progress is saved in this browser.')}</p>`;document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{state.kind=b.dataset.kind;save();renderReview();});$('#review-due').onclick=()=>startSession(true);$('#review-new').onclick=()=>startSession(false);}
function startSession(onlyDue,selected=selection()){selected=selected.filter(id=>!state.known.includes(id));const queue=makeQueue(langs,selected,state.reviews,state.kind,onlyDue);if(!queue.length){openModal(`<div class="big-icon">✧</div><h2>${!selected.length?t('Escolha seu próximo destino','Choose your next destination'):onlyDue?t('Revisões em dia!','All caught up!'):t('Tudo explorado por enquanto','All explored for now')}</h2><p>${!selected.length?t('Marque um idioma em Explorar ou restaure um idioma nas configurações.','Select a language in Explore or restore one in Settings.'):t('Não há cartões neste filtro agora. Escolha outro tipo, explore novos idiomas ou volte quando suas revisões vencerem.','No cards are available in this filter now. Choose another type, explore new languages or return when your reviews are due.')}</p>`);return;}session={queue,index:0,revealed:false,correct:null,options:null};renderSession();window.scrollTo(0,0);}
function current(){return session.queue[session.index];}
function promptAI(c,l){return t('Explique em português, para uma iniciante, a gramática e o uso cultural desta expressão em ','Explain in English, for a beginner, the grammar and cultural use of this expression in ')+lname(l)+': '+c.roman+' ('+c.native+(c.nativeAlt?' / '+c.nativeAlt:'')+'). '+t('Tradução proposta: ','Suggested translation: ')+meaning(c)+'. '+t('Analise palavra por palavra e indique diferenças de registro, gênero ou dialeto. Corrija possíveis erros e indique incertezas.','Break it down word by word and note differences in register, gender or dialect. Correct any errors and acknowledge uncertainty.');}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function renderSession(){syncChrome();const c=current(),l=langs.find(l=>l.id===c.lang),quiz=session.index%2===0;
if(!session.options){const others=l.cards.filter(x=>x.id!==c.id&&x.native!==c.native&&x.roman.toLocaleLowerCase()!==c.roman.toLocaleLowerCase());session.options=shuffle([c,...shuffle(others).slice(0,3)]);}
const topic=({ 'Primeiros encontros':t('Primeiros encontros','First encounters'),'Essenciais':t('Essenciais','Essentials'),'Na conversa':t('Na conversa','In conversation')})[c.topic];
app.innerHTML=`<section class="session"><div class="session-top"><button class="round" id="exit-session" aria-label="${t('Pausar sessão','Pause session')}">×</button><span>${lname(l)} · ${session.index+1} ${t('de','of')} ${session.queue.length}</span><span>✧</span></div><div class="progress"><div style="width:${session.index/session.queue.length*100}%"></div></div><div class="flash"><span class="tag">${c.type==='phrase'?t('Frase','Phrase'):t('Palavra','Word')} · ${topic}</span><p class="muted" style="font-size:12px;margin-top:22px">${quiz?t('Como você diria em '+lname(l)+'?','How would you say this in '+lname(l)+'?'):t('Tente lembrar o significado','Try to recall the meaning')}</p><div class="prompt">${quiz?esc(meaning(c)):scriptHTML(c,l)}</div>${!quiz?audioButton(c):''}${quiz?`<div class="options">${session.options.map(o=>`<button class="option ${session.revealed?(o.id===c.id?'correct':o.id===session.choice?'wrong':''):''}" data-answer="${o.id}" ${session.revealed?'disabled':''}>${scriptHTML(o,l)}</button>`).join('')}</div>`:''}${!session.revealed&&!quiz?`<button class="btn full" style="margin-top:28px" id="reveal">${t('Mostrar significado','Show meaning')}</button>`:''}${session.revealed?`<div class="translation">${quiz?scriptHTML(c,l):esc(meaning(c))}</div>${quiz?audioButton(c):''}<p class="smallprint" style="margin-top:10px">${quiz?(session.correct?t('Você reconheceu! Agora avalie sua lembrança.','You recognized it! Now rate your recall.'):t('Tudo bem — este é um bom momento para rever.','That’s okay — this is a good time to review.')):t('Quanto esforço foi necessário para lembrar?','How much effort did it take to remember?')}</p><div class="explain-actions"><button class="text-btn" id="grammar">${t('Entender a expressão','Understand the expression')}</button><a href="https://chatgpt.com/?q=${encodeURIComponent(promptAI(c,l))}" target="_blank" rel="noopener noreferrer">✧ ${t('Perguntar à IA','Ask AI')} ↗</a></div><div id="grammar-text"></div>`:''}</div>${session.revealed?`<div class="ratings">${[['again',t('De novo','Again')],['hard',t('Difícil','Hard')],['good',t('Lembrei','Remembered')],['easy',t('Fácil','Easy')]].map(([g,label])=>{const days=nextReview(state.reviews[c.id],g).interval;return `<button data-grade="${g}">${label}<span>${days<1?'10 min':Math.round(days)+' '+t('dia','day')+(Math.round(days)>1?'s':'')}</span></button>`;}).join('')}</div>`:''}<p class="session-footer">${quiz?t('Reconhecer','Recognize'):t('Recordar','Recall')} · ${t('Escrita nativa + transliteração','Native script + transliteration')}<br>${t('Áudio sintético, quando disponível','Synthetic audio, when available')}</p></section>`;
$('#exit-session').onclick=()=>navigate(page);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{session.revealed=true;session.choice=b.dataset.answer;session.correct=b.dataset.answer===c.id;renderSession();});if($('#reveal'))$('#reveal').onclick=()=>{session.revealed=true;renderSession();};if($('#grammar'))$('#grammar').onclick=()=>{const note=(state.ui==='en'?englishNotes:notes)[c.id]||lculture(l)+' '+t(`Neste cartão, “${c.roman}” significa “${meaning(c)}”. Para uma análise palavra por palavra, use “Perguntar à IA”, que abre o ChatGPT com a expressão pronta.`,`In this card, “${c.roman}” means “${meaning(c)}”. For a word-by-word breakdown, use “Ask AI”, which opens ChatGPT with the expression ready.`);$('#grammar-text').innerHTML=`<div class="grammar">${esc(note)}</div>`;};document.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>rate(b.dataset.grade));bindAudio();}
function rate(g){const c=current();state.reviews[c.id]=nextReview(state.reviews[c.id],g);const today=dateKey();state.daily[today]=(state.daily[today]||0)+1;save();session.index++;if(session.index>=session.queue.length){const count=session.queue.length;session=null;app.innerHTML=`<section class="session empty"><div class="big-icon">✺</div><div class="eyebrow">${t('MAIS UM PEDACINHO DO MUNDO','ANOTHER LITTLE PIECE OF THE WORLD')}</div><h1>${t('Boa viagem,<br><em>memória.</em>','Bon voyage,<br><em>memory.</em>')}</h1><p>${t(`Você estudou ${count} cartões. As próximas revisões já estão marcadas.`,`You studied ${count} cards. Your next reviews are scheduled.`)}</p><button class="btn" id="finish-session">${t('Ver meu passaporte','See my passport')} →</button><p class="smallprint" style="margin-top:20px">${volatile?t('O navegador não conseguiu salvar. Exporte seu progresso nas configurações.','The browser could not save. Export your progress in Settings.'):t('Progresso salvo neste navegador.','Progress saved in this browser.')}</p></section>`;$('#finish-session').onclick=()=>navigate('passaporte');return;}session.revealed=false;session.correct=null;session.choice=null;session.options=null;renderSession();}
function streak(){let n=0,d=new Date();if(!state.daily[dateKey(d)])d.setDate(d.getDate()-1);while(state.daily[dateKey(d)]){n++;d.setDate(d.getDate()-1);}return n;}
function renderPassport(){const visited=available().filter(l=>l.cards.some(c=>state.reviews[c.id]));app.innerHTML=`<div class="eyebrow">${t('COLECIONE CONVERSAS, NÃO FRONTEIRAS','COLLECT CONVERSATIONS, NOT BORDERS')}</div><h1>${t('Seu <em>passaporte.</em>','Your <em>passport.</em>')}</h1><p class="sub">${t('Cada idioma que você experimenta deixa uma marca na sua viagem.','Every language you try leaves a mark on your journey.')}</p><div class="stat-grid"><div class="stat"><strong>${visited.length}</strong><span>${t('idiomas experimentados','languages explored')}</span></div><div class="stat"><strong>${streak()}</strong><span>${t('dias seguidos','day streak')}</span></div><div class="stat"><strong>${Object.values(state.daily).reduce((a,b)=>a+b,0)}</strong><span>${t('cartões respondidos','cards answered')}</span></div></div><h2>${t('Carimbos da sua jornada','Stamps from your journey')}</h2>${visited.length?`<div class="stamps">${visited.map(l=>`<div class="stamp"><i>${regions.find(r=>r[0]===l.region)[2]}</i><b>${lname(l)}</b><span>${l.cards.filter(c=>state.reviews[c.id]).length} ${t('CARTÕES EXPLORADOS','CARDS EXPLORED')}</span></div>`).join('')}</div>`:`<div class="empty" style="margin-top:22px"><h2>${t('Seu primeiro carimbo espera por você.','Your first stamp is waiting.')}</h2><p>${t('Experimente uma sessão para começar sua coleção.','Try a session to start your collection.')}</p><button class="btn" id="first-stamp">${t('Descobrir idiomas','Discover languages')} →</button></div>`}<p class="notice">${t('Os carimbos registram contato com o idioma, não fluência. Idiomas marcados como “Já sei” ficam ocultos, mas seu histórico é preservado.','Stamps record contact with a language, not fluency. Languages marked “Already know” are hidden, but their history is preserved.')}</p>`;if($('#first-stamp'))$('#first-stamp').onclick=()=>navigate('explorar');}
function about(){const sourceNames=['Navajo: phrases and context','K’iche’: University of Texas course','Ewe: phrases and recordings','Tetum: expressions and variants','Quechua: diversity of varieties'];openModal(`<span class="eyebrow">${t('EDIÇÃO INICIAL','FIRST EDITION')}</span><h2>${t('Pequenos começos,<br>um grande mapa.','Small beginnings,<br>a big map.')}</h2><p>${t(`Hoje: ${langs.length} idiomas e ${allCards.length} cartões. A meta é 100 frases e 300 palavras distintas por idioma; esta versão ainda não tem esse volume.`,`Today: ${langs.length} languages and ${allCards.length} cards. The goal is 100 phrases and 300 distinct words per language; this version does not yet have that volume.`)}</p><p>${t('O material é introdutório e ainda precisa de revisão por falantes. Não há promessa de certificação A1. As regiões são rotas de descoberta, não limites geográficos de cada língua.','The material is introductory and still needs speaker review. It does not promise A1 certification. Regions are discovery routes, not geographic limits for each language.')}</p><p>${t('Áudio: voz sintética do aparelho, quando disponível. Escrita nativa acima e romanização abaixo, quando são diferentes. A romanização é um apoio de leitura, não pronúncia em português; algumas formas não marcam todos os tons.','Audio uses a synthetic device voice, when available. Native writing appears above romanization when they differ. Romanization is a reading aid, not English pronunciation; some forms do not mark every tone.')}</p><p>${t('O botão de IA abre o ChatGPT. As notas internas são fixas; não há IA integrada nesta versão.','The AI button opens ChatGPT. In-app notes are fixed; this version has no integrated AI.')}</p><h3>${t('Referências consultadas','References consulted')}</h3><div class="source-list">${sources.map(([name,url],i)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${state.ui==='en'?(sources[i][2]||sourceNames[i]):name} ↗</a>`).join('')}</div><p class="smallprint">${t('Essas referências cobrem partes do material, não a revisão integral do catálogo.','These references cover parts of the material, not a full review of the catalogue.')}</p>`);}
function settings(){openModal(`<span class="eyebrow">${t('DO SEU JEITO','YOUR OWN WAY')}</span><h2>${t('Preferências de viagem','Travel preferences')}</h2><label for="settings-language">${t('Idioma do site','Site language')}</label><select id="settings-language"><option value="pt" ${state.ui==='pt'?'selected':''}>Português</option><option value="en" ${state.ui==='en'?'selected':''}>English</option></select><label for="speed">${t('Velocidade do áudio','Audio speed')}</label><select id="speed"><option value="normal" ${!state.slow?'selected':''}>${t('Normal','Normal')}</option><option value="slow" ${state.slow?'selected':''}>${t('Devagar','Slow')}</option></select><p class="smallprint">${t('As vozes disponíveis dependem do aparelho e navegador.','Available voices depend on your device and browser.')}</p><h3 style="margin-top:24px">${t('Idiomas que já sei','Languages I already know')} · ${state.known.length}</h3><p class="smallprint">${t('Ficam ocultos do catálogo, da sua rota e de todas as sessões. Restaurar traz o idioma de volta com seu histórico.','Hidden from the catalogue, your route and all sessions. Restoring a language brings it back with its history.')}</p>${state.known.length?`<div class="known-list">${state.known.map(id=>`<div class="word-row"><b>${lname(langs.find(l=>l.id===id))}</b><button class="btn secondary small" data-restore="${id}">${t('Restaurar','Restore')}</button></div>`).join('')}</div>`:`<p class="smallprint">${t('Nenhum idioma oculto. Use “Já sei este idioma” no catálogo.','No hidden languages. Use “I already know this language” in the catalogue.')}</p>`}<h3 style="margin-top:24px">${t('Seu progresso','Your progress')}</h3><p class="smallprint">${t('Salvo neste navegador. Exporte uma cópia para guardar ou mudar de aparelho. Importar substitui o progresso atual após confirmação.','Saved in this browser. Export a backup to keep it or move devices. Importing replaces current progress after confirmation.')}</p><div class="hero-buttons"><button class="btn secondary small" id="export">${t('Exportar progresso','Export progress')}</button><button class="btn secondary small" id="import">${t('Importar progresso','Import progress')}</button></div><input type="file" id="file" accept="application/json,.json" hidden><button class="text-btn" id="about-settings" style="margin-top:20px">${t('Sobre o conteúdo e as fontes','About content and sources')}</button>`);
$('#settings-language').onchange=e=>{changeUI(e.target.value);settings();};$('#speed').onchange=e=>{state.slow=e.target.value==='slow';save();};document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{restoreKnown(b.dataset.restore);settings();});$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='passaporte-progresso.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error();const data=JSON.parse(await file.text()),imported=migrateState(data.state);if(![1,2].includes(data.version)||!validState(imported))throw Error();$('#modal-body').innerHTML=`<h2>${t('Substituir o progresso?','Replace your progress?')}</h2><p>${t('O arquivo é válido. A importação substitui cartões, preferências e rota atuais.','The file is valid. Importing replaces your current cards, preferences and route.')}</p><button class="btn" id="confirm-import">${t('Importar e substituir','Import and replace')}</button>`;$('#confirm-import').onclick=()=>{state=cleanState(imported);session=null;save();$('#modal').close();render();toast(t('Progresso importado.','Progress imported.'));};}catch{toast(t('Arquivo inválido. Use uma cópia exportada pelo Passaporte.','Invalid file. Use a backup exported by Passaporte.'));}};$('#about-settings').onclick=about;}
$('#settings').onclick=settings;$('#ui-language').onchange=e=>changeUI(e.target.value);$('.modal-close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();region='all';search='';navigate('explorar');};render();if(volatile)toast(t('Progresso anterior indisponível. Importe uma cópia para restaurar.','Previous progress unavailable. Import a backup to restore it.'));

function collectionsHTML(){return `<section class="collections" aria-label="${t('Seleções de idiomas','Language collections')}"><div class="section-row"><div><div class="eyebrow">${t('ESCOLHA O TAMANHO DA SUA VIAGEM','CHOOSE THE SIZE OF YOUR JOURNEY')}</div><h2>${t('Um passaporte do seu jeito.','A passport that fits you.')}</h2><p>${t('Comece pequeno, descubra novas vozes ou explore uma região.','Start small, discover new voices or explore a region.')}</p></div></div><div class="collection-grid">${collections.map(c=>`<button class="collection-card ${c.id===catalogCollection?'chosen':''}" data-collection="${c.id}" style="--tint:${c.tint}" aria-pressed="${c.id===catalogCollection}"><span class="collection-icon">${c.icon}</span><h3>${t(c.pt,c.en)}</h3><p>${t(c.descPt,c.descEn)}</p><span class="collection-count">${c.id==='regions'?t('9 regiões','9 regions'):c.ids.filter(id=>!state.known.includes(id)).length+' '+t('idiomas disponíveis','languages available')} →</span></button>`).join('')}</div></section>`;}
function bindCollections(){document.querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>openCollection(b.dataset.collection));}
function openCollection(id){if(!collections.some(c=>c.id===id))return;catalogCollection=id;region='all';search='';renderExplore();$('#catalog-section').scrollIntoView({behavior:'smooth',block:'start'});}
function selectionIntro(preset,items){const isRegional=preset.id==='regions';const r=regions.find(r=>r[0]===region);const title=isRegional?(r?rname(r):t('Sua busca','Your search')):t(preset.pt,preset.en);const full=isRegional?langs.filter(l=>region==='all'||l.region===region).map(l=>l.id):preset.ids;const hidden=full.filter(id=>state.known.includes(id)).length;return `<div class="selection-intro"><div class="eyebrow">${t('SUA PRÓXIMA ROTA','YOUR NEXT ROUTE')}</div><h3>${title}</h3><p>${isRegional?t('Uma seleção para explorar esta parte do mundo.','A selection to explore this part of the world.'):t(preset.descPt,preset.descEn)}</p><p class="smallprint">${t('“Usar esta seleção” troca os idiomas da Minha rota. O progresso de cada idioma continua salvo.','“Use this selection” changes the languages on My route. Each language’s progress remains saved.')}${hidden?' '+hidden+' '+t('já conhecidos foram ocultados.','already-known languages are hidden.'):''}</p></div>`;}
